import{_ as t,o as a,c as r,a4 as d}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Land-purchase source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/15-land-purchase-profile.md","filePath":"reference/15-land-purchase-profile.md","lastUpdated":1788593217000}'),i={name:"reference/15-land-purchase-profile.md"};function n(o,e,s,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="land-purchase-source-profile" tabindex="-1">Land-purchase source profile <a class="header-anchor" href="#land-purchase-source-profile" aria-label="Permalink to &quot;Land-purchase source profile&quot;">​</a></h1><h2 id="authority-and-corrected-scope" tabindex="-1">Authority and corrected scope <a class="header-anchor" href="#authority-and-corrected-scope" aria-label="Permalink to &quot;Authority and corrected scope&quot;">​</a></h2><p>The activity key remains <code>property</code> for API compatibility, but its user-facing label is now <strong>Land purchase (for building)</strong>. B. V. Raman treats buying land for building and buying a completed house as separate elections with different criteria. One generic “Property / Land purchase” profile would therefore make an authority claim broader than its evidence.</p><p>This profile uses B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter XII, “Buying Lands for Buildings,” internal printed page 54 (physical PDF page 58) in the inspected 2020 Chistabo derivative:</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">inspected 2020 Chistabo derivative</a></p><p>Raman is a modern synthesis and secondary authority, not primary scripture.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Locator</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Fourteen named asterisms are best for buying land</td><td>internal printed p. 54 (physical PDF p. 58)</td><td><code>allowed_nakshatras</code></td><td>The active slot-time Nakshatra must be one of the fourteen names.</td></tr><tr><td>Rikta Tithis must be scrupulously avoided</td><td>internal printed p. 54 (physical PDF p. 58)</td><td><code>avoid_tithi_numbers: [4, 9, 14]</code></td><td>Both Pakshas are handled by active Tithi number; Rikta slots are rejected rather than merely down-ranked.</td></tr><tr><td>Monday, Wednesday, Thursday and Saturday are good</td><td>internal printed p. 54 (physical PDF p. 58)</td><td><code>allowed_varas</code>; <code>prefer_vara</code></td><td>Only those four sunrise weekdays are admitted and the match remains visible in the score explanation.</td></tr><tr><td>Tuesday is recommended by some writers, but Raman rejects it</td><td>internal printed p. 54 (physical PDF p. 58)</td><td><code>allowed_varas</code></td><td>Tuesday is outside the admitted list. The implementation does not erase the textual disagreement; it records that this is Raman&#39;s configured profile.</td></tr><tr><td>At final negotiations, preferably use a fixed rising Rasi</td><td>internal printed p. 54 (physical PDF p. 58)</td><td><code>prefer_lagna_class: Sthira</code></td><td>Fixed Lagna receives the disclosed activity bonus; it is a preference, not a hard gate.</td></tr><tr><td>Guru in Kendra/Trikona; Mangala in 11th and not Lagna</td><td>internal printed p. 54 (physical PDF p. 58)</td><td><code>ELECTION_CHART_RULES[property]</code></td><td>The Drik browser post-screen counts the first two as preferences only across every sampled state and rejects Mangala in Lagna at any sample (edges and both sides of known interior Lagna transitions).</td></tr><tr><td>Weekday lord in Lagna; harmonious Lagna/7th lords; avoid 11th lord in 12th</td><td>internal printed p. 54 (physical PDF p. 58)</td><td><code>manual_checks</code></td><td>Lordship and relationship judgment remain for practitioner review.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>Python, MCP, and browser consume the same generated activity profile. MCP exposes the stable <code>muhurta.land_purchase.building</code> claim identifier and keeps the complete chart wording in <code>manual_checks</code>. The Drik browser adds the bounded chart post-screen above; it does not make Python/MCP chart-aware. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p><p>This profile must not be presented as an election for buying a completed house. Raman gives that a separate Nanda-Tithi, Thursday/Friday and Nakshatra profile. Adding that as its own activity requires a separate reviewed feature. Legal due diligence, title verification, valuation, financing, soil testing and structural advice remain professional—not astrological—requirements.</p>',11)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
